package io.github.phiscript.root;
import android.app.*;import android.widget.*;import android.text.InputType;import io.github.phiscript.AppSettings;import io.github.phiscript.input.TapMod;
public final class TapSettings {
    public static void open(Activity a){if(RootPanel.blocked(a))return;AppSettings prefs=new AppSettings(a);LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding(UiDesign.dp(a,24),UiDesign.dp(a,12),UiDesign.dp(a,24),UiDesign.dp(a,12));
        Switch enabled=new Switch(a);enabled.setText("启用点击位置调整");enabled.setChecked(Boolean.parseBoolean(prefs.text("tapmod_enabled","true")));box.addView(enabled);
        Switch noise=new Switch(a);noise.setText("避开谱面噪域");noise.setChecked(Boolean.parseBoolean(prefs.text("tap_noise_avoid","true")));box.addView(noise);
        TextView guardLabel=new TextView(a);guardLabel.setText("噪域时钟误差保护");box.addView(guardLabel);
        Spinner guard=new Spinner(a);guard.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"标准：提前 4 ms / 滞后 12 ms","保守：前后 16 ms","更保守：前后 24 ms"}));String configured=prefs.text("tap_noise_clock_guard_ms","0");guard.setSelection("16".equals(configured)?1:"24".equals(configured)?2:0);box.addView(guard);
        String[] labels={"沿判定线法线偏移（屏幕高度 ‰，0–200）","随机偏移范围（屏幕高度 ±‰，0–20）","噪域避让最大距离（屏幕高度 ‰，0–2000）"};String[] keys={"tap_vertical_permille","tap_jitter_permille","tap_noise_escape_permille"},defaults={"35","6","2000"};int[] maximum={200,20,2000};EditText[] values=new EditText[3];
        for(int i=0;i<3;i++){TextView label=new TextView(a);label.setText(labels[i]);box.addView(label);EditText edit=new EditText(a);edit.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);edit.setText(prefs.text(keys[i],defaults[i]));values[i]=edit;box.addView(edit);}
        TextView help=new TextView(a);help.setText("随机偏移在预计算时生成；重新计算触点可刷新，同一长按保持偏移稳定。先沿判定线法线选择安全间隙的中间位置，再尝试同判定带两侧的安全位置。仅能处理谱面文件保留的噪域数据。\n\n时钟误差保护会把触点附近时刻也纳入噪域检查，适合已校准但仍疑似在区域启闭附近漏打的设备。保守档可能让短暂安全时隙抬指；默认标准档。旋转和缩放仍采用采样与关键帧检查。");box.addView(help);ScrollView scroll=new ScrollView(a);scroll.addView(box);
        AlertDialog dialog=UiDesign.dialog(a,"噪域与随机点击").setView(scroll).setPositiveButton("保存",null).setNegativeButton("取消",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(RootPanel.blocked(a))return;for(int i=0;i<3;i++){try{float n=Float.parseFloat(values[i].getText().toString());if(!Float.isFinite(n)||n<0||n>maximum[i])throw new NumberFormatException();}catch(Exception e){values[i].setError("请输入 0–"+maximum[i]);return;}}
            prefs.save("tapmod_enabled",Boolean.toString(enabled.isChecked()));prefs.save("tap_noise_avoid",Boolean.toString(noise.isChecked()));prefs.save("tap_noise_clock_guard_ms",guard.getSelectedItemPosition()==1?"16":guard.getSelectedItemPosition()==2?"24":"0");for(int i=0;i<3;i++)prefs.save(keys[i],values[i].getText().toString());TapMod.init(a);dialog.dismiss();}));UiDesign.show(dialog);
    }
}
